module benchmark/solution

export type Tree = Leaf | Node(Tree, int, Tree)

export pure func insert(tree: Tree, value: int) -> Tree =
  match tree {
    Leaf => Node(Leaf, value, Leaf),
    Node(left, key, right) =>
      if value < key then Node(insert(left, value), key, right)
      else if value > key then Node(left, key, insert(right, value))
      else tree
  }

export pure func contains(tree: Tree, value: int) -> bool =
  match tree {
    Leaf => false,
    Node(left, key, right) =>
      if value == key then true
      else if value < key then contains(left, value)
      else contains(right, value)
  }

export pure func size(tree: Tree) -> int =
  match tree {
    Leaf => 0,
    Node(left, key, right) => 1 + size(left) + size(right)
  }

export pure func isBST(tree: Tree, lower: int, upper: int) -> bool =
  match tree {
    Leaf => true,
    Node(left, key, right) =>
      lower < key && key < upper &&
      isBST(left, lower, key) && isBST(right, key, upper)
  }

export pure func insertPreservesBST(value: int) -> bool ! {}
ensures { result == true }
{
  if value > -999999 && value < 999999
  then isBST(insert(Leaf, value), -999999, 999999)
  else true
}

export pure func insertThenFind(value: int) -> bool ! {}
ensures { result == true }
{
  contains(insert(Leaf, value), value)
}

export func main() -> () ! {IO} {
  let tree = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(tree)));
  println(show(contains(tree, 3)));
  println(show(contains(tree, 4)));
  println(show(isBST(tree, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}
